<?php
namespace App\Notifications;
use App\Models\Pembayaran; use App\Filament\Admin\Resources\Pembayarans\PembayaranResource; use Filament\Actions\Action; use Filament\Notifications\Notification as FilamentNotification; use Illuminate\Bus\Queueable; use Illuminate\Notifications\Notification;
class PembayaranDibuatUntukSupplier extends Notification { use Queueable; public function __construct(public Pembayaran $pembayaran){} public function via(object $notifiable):array{return ['database'];} public function toDatabase(object $notifiable):array{ $no='PAY-'.str_pad((string)$this->pembayaran->id,5,'0',STR_PAD_LEFT); return FilamentNotification::make()->title('Pembayaran Menunggu Persetujuan')->body("{$no} dari klinik menunggu persetujuan Anda. Silakan periksa bukti pembayaran dan konfirmasi.")->icon('heroicon-o-banknotes')->iconColor('warning')->actions([Action::make('lihat')->label('Periksa Pembayaran')->url(PembayaranResource::getUrl('view',['record'=>$this->pembayaran->getKey()]))])->getDatabaseMessage(); } }
